16: export function profileImageUrlUpload () {
17:   return async (req: Request, res: Response, next: NextFunction) => {
18:     if (req.body.imageUrl !== undefined) {
19:       const url = req.body.imageUrl
20:       if (url.match(/(.)*solve\/challenges\/server-side(.)*/) !== null) req.app.locals.abused_ssrf_bug = true
21:       const loggedInUser = security.authenticatedUsers.get(req.cookies.token)
22:       if (loggedInUser) {
23:         try {
24:           const response = await fetch(url)
25:           if (!response.ok || !response.body) {
26:             throw new Error('url returned a non-OK status code or an empty body')
27:           }
28:           const ext = ['jpg', 'jpeg', 'png', 'svg', 'gif'].includes(url.split('.').slice(-1)[0].toLowerCase()) ? url.split('.').slice(-1)[0].toLowerCase() : 'jpg'
29:           const fileStream = fs.createWriteStream(`frontend/dist/frontend/assets/public/images/uploads/${loggedInUser.data.id}.${ext}`, { flags: 'w' })
30:           await finished(Readable.fromWeb(response.body as any).pipe(fileStream))
31:           const user = await UserModel.findByPk(loggedInUser.data.id)
32:           await user?.update({ profileImage: `/assets/public/images/uploads/${loggedInUser.data.id}.${ext}` })
