38:           } catch (error) {
39:             next(error)
40:             return
41:           }
42:         }
43:       } else {
44:         next(new Error('Blocked illegal activity by ' + req.socket.remoteAddress))
45:         return
46:       }
47:     }
48:     res.location(process.env.BASE_PATH + '/profile')
49:     res.redirect(process.env.BASE_PATH + '/profile')
50:   }
51: }

